#!/usr/bin/env python
"""The Opus 5.5 tools organiser on the whole pan test split (scripts/81b), scored per operator next to the comparables of
results/collected/RESULTS_pan_comparables.md, written to results/collected/RESULTS_organiser_pan.md and results/organiser/pan_organiser.json.
cancer_type comes from the aliased rerun (PHASES=ct_alias EXTRA=--alias): the first run saw the TCGA barcode, whose tissue
source site code identifies the cancer type, and cited it in 1,303 of 1,393 reasons; that number is reported as the leak.
The 995 composite questions come from an aliased rerun as well (NAME=opus55_tools_pan_alias PHASES=composites EXTRA=--alias);
the first composite run is reported next to it.
    PYTHONPATH=src OPSIS_DATA=... python scripts/88c_pan_organiser.py"""
import json, glob, re, collections, os, sys
sys.path.insert(0, "src"); from opsis import paths
OUT = f"{paths.ROOT}/results/organiser"; NAME = "opus55_tools_pan"
PAT = re.compile(r"barcode|tissue source|source site|TSS|TCGA-[A-Z0-9]{2}\b|site code|institution|contribut", re.I)
def load(pattern): return [json.loads(l) for f in sorted(glob.glob(f"{OUT}/{pattern}")) for l in open(f)]
first = [r for f in sorted(glob.glob(f"{OUT}/{NAME}_composites_s?.jsonl") + glob.glob(f"{OUT}/{NAME}_synoptic_s?.jsonl") + glob.glob(f"{OUT}/{NAME}_tables_s?.jsonl")) for r in [json.loads(l) for l in open(f)]]
alias = load(f"{NAME}_ct_alias_s?.jsonl")
COMPOSITES = ["high_grade_and_lvi", "precursor_type", "necrosis_and_high_mitotic", "grade_from_components", "dcis_with_comedo"]
# the composite questions were rerun with the alias too (NAME=opus55_tools_pan_alias PHASES=composites EXTRA=--alias); the rerun replaces the first run once it covers every composite question
alias_comp = load(f"{NAME}_alias_composites_s?.jsonl"); first_comp = [r for r in first if r["operator"] in COMPOSITES]
USE_ALIAS_COMP = len(alias_comp) > 0 and {r["qid"] for r in alias_comp} >= {r["qid"] for r in first_comp}
rows = [r for r in first if r["operator"] != "cancer_type" and not (USE_ALIAS_COMP and r["operator"] in COMPOSITES)] + alias + (alias_comp if USE_ALIAS_COMP else [])
leak = [r for r in first if r["operator"] == "cancer_type"]
def acc(rs): return sum(r.get("correct", 0) or 0 for r in rs) / len(rs) if rs else float("nan")
def mentions(rs): return sum(bool(PAT.search(r.get("text") or "")) for r in rs)
# comparables from the markdown table of scripts/86 (test split section)
comp = {}; hdr = None
for line in open(f"{paths.ROOT}/results/collected/RESULTS_pan_comparables.md"):
    if line.startswith("## Held out"): break
    c = [x.strip() for x in line.strip().strip("|").split("|")]
    if c[0] == "operator": hdr = {h: i for i, h in enumerate(c)}; continue
    if hdr and len(c) == len(hdr) and not c[0].startswith("-"):
        g = lambda h: c[hdr[h]]
        comp[c[0]] = dict(maj=g("majority"), ours=g("Opsis-S (3 seeds)").split(" ")[0], titan=g("TITAN probe"), titan_zs=g("TITAN zero shot"), prism=g("PRISM2 probe"), prism_zs=g("PRISM2 zero shot"))
by = collections.defaultdict(list)
for r in rows: by[r["operator"]].append(r)
by1 = collections.defaultdict(list)
for r in first: by1[r["operator"]].append(r)
ORDER = ["high_grade_and_lvi", "precursor_type", "necrosis_and_high_mitotic", "grade_from_components", "dcis_with_comedo", "pan_grade", "pan_lvi", "pan_pni", "pan_necrosis", "pan_precursor", "pan_mitotic", "pan_multifocal", "pan_infiltrate", "cancer_type", "molecular_subtype", "tumor_purity_bin", "leukocyte_fraction_bin"]
L = ["# Opus 5.5 tools organiser on the whole pan test split (generated by scripts/88c_pan_organiser.py)", "",
     f"Claude Opus 5.5 through the Claude Code CLI with the four Opsis tools (slide_info, ask_slide, tile_evidence, ask_region), every question of the test split (1,393 slides), scripts/81b in three phases of four shards. cancer_type and the five composites come from the aliased reruns (--alias), the other rows from the first run. {len(rows):,} questions scored, {sum(r.get('pred') is None for r in rows)} without a parsable answer (counted wrong). The comparables are the full test probes of results/collected/RESULTS_pan_comparables.md: Opsis-S is the slide readout alone (3 seeds; on the composite rows it answers an operator token it never trained, since the composite family was excluded from training; the rule composed answers are in results/organiser/rules_composites.json, scripts/88e), the TITAN and PRISM2 probes train one classifier per operator on the training split labels, including the composites. Bold: best of the four scored columns on the row.", "",
     "| operator | n | majority | organiser: Opus 5.5 + Opsis tools | Opsis-S | TITAN probe | PRISM2 probe | PRISM2 zero shot |", "|---|---|---|---|---|---|---|---|"]
js = {}
for op in ORDER:
    rs = by.get(op, []); c = comp.get(op, {}); a = acc(rs)
    cells = {"org": a, "ours": float(c.get("ours") or "nan"), "titan": float(c.get("titan") or "nan"), "prism": float(c.get("prism") or "nan")}
    best = max(v for v in cells.values() if v == v)
    def f(k): v = cells[k]; return "" if v != v else (f"**{v:.3f}**" if abs(v - best) < 5e-4 else f"{v:.3f}")
    n = f"{len(rs)}" + ("" if op != "cancer_type" or len(alias) >= 1393 else " (aliased rerun in progress)")
    L.append(f"| {op} | {n} | {c.get('maj', '')} | {f('org')} | {f('ours')} | {f('titan')} | {f('prism')} | {c.get('prism_zs', '')} |")
    js[op] = dict(n=len(rs), organiser=round(a, 4), **{k: cells[k] for k in ("ours", "titan", "prism")})
groups = {"composites": ORDER[:5], "synoptic": ORDER[5:13], "table fields": ORDER[13:]}
L += ["", "| group | n | organiser | majority |", "|---|---|---|---|"]
for g, ops in groups.items():
    rs = [r for op in ops for r in by.get(op, [])]
    maj = sum(float(comp[op]["maj"]) * len(by.get(op, [])) for op in ops if op in comp) / max(1, len(rs))
    L.append(f"| {g} | {len(rs)} | {acc(rs):.3f} | {maj:.3f} |"); js[g] = dict(n=len(rs), organiser=round(acc(rs), 4), majority=round(maj, 4))
cost = sum(r.get("cost_usd") or 0 for r in rows); calls = sum(r.get("steps", 0) for r in rows) / len(rows); tok = sum(r["usage"]["prompt"] for r in rows) / len(rows); out = sum(r["usage"]["completion"] for r in rows) / len(rows); sec = sum(r.get("seconds", 0) for r in rows) / len(rows)
L += ["", f"Per question: {calls:.2f} tool calls, {tok:,.0f} input tokens, {out:.0f} output tokens, {sec:.1f} s, list price ${cost / len(rows):.3f} (${cost:,.0f} for the split).", "",
      "## The barcode leak on cancer_type", "",
      f"The first cancer_type run showed the organiser the TCGA slide name. Its tissue source site code (TCGA-06 is Henry Ford, a glioblastoma site) identifies the project for most sites, and the model knows the mapping: {mentions(leak)} of {len(leak)} reasons cite the barcode or the contributing site, accuracy {acc(leak):.3f} ({acc([r for r in leak if PAT.search(r.get('text') or '')]):.3f} on the citing episodes, {acc([r for r in leak if not PAT.search(r.get('text') or '')]):.3f} on the rest), against 0.937 for the slide readout it was relaying. slide_info also returned the project (called {sum(any('slide_info' in (t.get('tool') or '') for t in r.get('tools') or []) for r in leak)} times). The rerun (--alias) names the slide slide_<md5 prefix>, resolves the alias inside the MCP server, and hides project and patient in slide_info: {mentions(alias)} of {len(alias)} reasons mention a barcode, accuracy {acc(alias):.3f}. The table above uses the rerun.", "",
      "Barcode mentions in the other operators of the first run, where the site code carries no grade, invasion, purity or subtype label: " + ", ".join(f"{op} {mentions(by1[op])}/{len(by1[op])}" for op in ORDER if op != "cancer_type") + ". The 189 question BRCA organiser set: Opus 5.5 tools 4 of 189, eyes 12 of 189, the three OpenAI models 0 (all BRCA, so no cancer type to infer).", "",
      "## Reading", "",
      "- Composites (never trained, aliased rerun): the organiser composes them from the primitive tools and lands next to the probes that were trained on each composite's labels on the largest row (high grade with LVI, n 479: " + f"{js['high_grade_and_lvi']['organiser']:.3f} against {js['high_grade_and_lvi']['titan']:.3f} and {js['high_grade_and_lvi']['prism']:.3f}" + "), and 6 to 13 points below them on the other four rows (" + ", ".join(f"{op} {js[op]['organiser']:.3f} against {js[op]['titan']:.3f} and {js[op]['prism']:.3f}" for op in COMPOSITES[1:]) + "). The slide readout answering the untrained composite operator token is far below on every composite row (precursor type 0.098); with a fixed rule over its primitives it reaches 0.782 on high grade with LVI and 0.890 on necrosis with high mitotic, and has no rule for the other three (scripts/88e).",
      "- Composites, first run against the aliased rerun (same " + f"{len(first_comp)} questions): " + ", ".join(f"{op} {acc(by1[op]):.3f} to {acc(by[op]):.3f}" for op in COMPOSITES) + f", all {acc(first_comp):.3f} to {acc(alias_comp):.3f}" + ". " + (lambda a, c, n: f"On precursor type the change is the same on the {len(c)} questions whose first run reason cited the barcode ({acc(c):.3f} to {acc([a[r['qid']] for r in c]):.3f}) and on the other {len(n)} ({acc(n):.3f} to {acc([a[r['qid']] for r in n]):.3f}).")({r["qid"]: r for r in alias_comp}, [r for r in by1["precursor_type"] if PAT.search(r.get("text") or "")], [r for r in by1["precursor_type"] if not PAT.search(r.get("text") or "")]) if USE_ALIAS_COMP else "",
      "- Synoptic: the organiser relays ask_slide (0.722 against 0.703 for one seed of Opsis-S over the eight operators); the small gains come from the few questions where it consults tile_evidence or ask_region in addition.",
      "- Table fields: with the alias, cancer_type is the slide readout's number; molecular subtype, purity and leukocyte fraction are at the readout's level, below the TITAN probe by 2 to 4 points.",
      "- The 189 question subset (results/collected/RESULTS_organiser_opus55.md) overstates the composites: 0.95 and 0.88 on 21 and 8 questions become " + f"{js['high_grade_and_lvi']['organiser']:.2f} and {js['necrosis_and_high_mitotic']['organiser']:.2f}" + " on 479 and 146."]
open(f"{paths.ROOT}/results/collected/RESULTS_organiser_pan.md", "w").write("\n".join(L) + "\n"); json.dump(js, open(f"{OUT}/pan_organiser.json", "w"), indent=1)
print("\n".join(L[4:30]))
